const notes = new Map();
let counter = 0;

const tools = [
  {
    name: 'note_create',
    description: 'Create a note with a non-empty title and body.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Title of the note.' },
        body: { type: 'string', description: 'Body of the note.' },
      },
      required: ['title', 'body'],
      additionalProperties: false,
    },
  },
  {
    name: 'note_get',
    description: 'Retrieve a note by its id.',
    inputSchema: {
      type: 'object',
      properties: {
        note_id: { type: 'string', description: 'Id of the note to retrieve.' },
      },
      required: ['note_id'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return tools;
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

export async function callTool(name, args = {}) {
  if (name === 'note_create') {
    if (!isNonEmptyString(args.title)) {
      throw new Error('title is required and must be a non-empty string');
    }
    if (!isNonEmptyString(args.body)) {
      throw new Error('body is required and must be a non-empty string');
    }
    const id = `n${++counter}`;
    notes.set(id, { id, title: args.title, body: args.body });
    return {
      content: [
        {
          type: 'text',
          text: `Created note ${id} with title "${args.title}".`,
        },
      ],
    };
  }

  if (name === 'note_get') {
    if (!isNonEmptyString(args.note_id)) {
      throw new Error('note_id is required and must be a non-empty string');
    }
    const note = notes.get(args.note_id);
    if (!note) {
      throw new Error(`note ${args.note_id} not found`);
    }
    return {
      content: [
        {
          type: 'text',
          text: `${note.title}\n\n${note.body}`,
        },
      ],
    };
  }

  throw new Error(`unknown tool: ${name}`);
}

