import('./server.mjs').then(async ({listTools, callTool}) => {
  // listTools
  console.log('tools:', JSON.stringify(await listTools()));
  // create
  const c = await callTool('note_create', {title:'Hello', body:'World'});
  console.log('create:', JSON.stringify(c));
  const id = c.content[0].text.match(/n\d+/)[0];
  // get
  const g = await callTool('note_get', {note_id: id});
  console.log('get:', JSON.stringify(g));
  // invalid: empty title
  try { await callTool('note_create', {title:'', body:'B'}); console.log('ERR: should reject empty title'); }
  catch(e){ console.log('reject empty title OK:', e.message); }
  // invalid: missing body
  try { await callTool('note_create', {title:'A'}); console.log('ERR: should reject missing body'); }
  catch(e){ console.log('reject missing body OK:', e.message); }
  // invalid: missing note_id
  try { await callTool('note_get', {}); console.log('ERR: should reject missing note_id'); }
  catch(e){ console.log('reject missing note_id OK:', e.message); }
  // not found
  try { await callTool('note_get', {note_id:'n9999'}); console.log('ERR: should reject not found'); }
  catch(e){ console.log('reject not found OK:', e.message); }
  // unknown tool
  try { await callTool('frob', {}); console.log('ERR: should reject unknown'); }
  catch(e){ console.log('reject unknown OK:', e.message); }
  // stable ids - second note gets n2
  const c2 = await callTool('note_create', {title:'X', body:'Y'});
  const id2 = c2.content[0].text.match(/n\d+/)[0];
  console.log('second id stable:', id2 === 'n2');
});
